        assumeTrue(buggyIf);

        double res = Double.NaN;
        String exc = "none";
        try {
            FDistributionImpl dist = new FDistributionImpl(numDf, denDf);
            res = dist.inverseCumulativeProbability(p);
        } catch (Exception e) {
            exc = e.getClass().getName();
        }
